'use strict';
const $=id=>document.getElementById(id),cfg=window.CCAR_CONFIG||{},connected=!!(cfg.supabaseUrl&&cfg.supabaseAnonKey);
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(Number(n)||0);
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const photoURL=path=>cfg.supabaseUrl+'/storage/v1/object/public/vehicle-photos/'+path.split('/').map(encodeURIComponent).join('/');
const statusLabel={draft:'Rascunho',published:'Disponível',sold:'Vendido'};
let session=null,vehicles=[],insights=new Map(),dailySeries=[],privateIndex=new Map(),photoItems=[],draggedPhotoIndex=null,currentPrivateVehicle=null,statusTimer=null;

function saveSession(value){session=value;if(value)sessionStorage.setItem('ccar-session',JSON.stringify(value));else sessionStorage.removeItem('ccar-session');}
function message(text,error=false){clearTimeout(statusTimer);$('adminStatus').hidden=!text;$('adminStatus').textContent=text;$('adminStatus').classList.toggle('is-error',error);if(text&&!error)statusTimer=setTimeout(()=>{$('adminStatus').hidden=true;},5000);}
async function request(path,options={},authorized=false){
 if(!connected)throw Error('Conecte o Supabase para ativar este recurso.');
 if(authorized&&!session?.access_token)throw Error('Entre novamente para continuar.');
 if(authorized&&session.expires_at<Date.now()/1000+60){const refresh=await fetch(cfg.supabaseUrl+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:cfg.supabaseAnonKey,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});if(!refresh.ok){saveSession(null);throw Error('Sua sessão expirou. Entre novamente.');}const next=await refresh.json();saveSession({...next,expires_at:Date.now()/1000+next.expires_in});}
 const headers={apikey:cfg.supabaseAnonKey,...(authorized?{Authorization:'Bearer '+session.access_token}:{}),...options.headers};
 const response=await fetch(cfg.supabaseUrl+path,{...options,headers});
 if(!response.ok){const body=await response.json().catch(()=>({}));throw Error(body.message||body.msg||body.error_description||'Não foi possível concluir.');}
 if(response.status===204)return null;return response.json().catch(()=>null);
}
function showLogin(text=''){$('adminLogin').hidden=false;$('adminWorkspace').hidden=true;if(text){$('adminSetupNotice').hidden=false;$('adminSetupNotice').textContent=text;}}
function clearPreviews(){photoItems.filter(item=>item.kind==='new').forEach(item=>URL.revokeObjectURL(item.url));photoItems=[];}
function closeDialog(id){if($(id).open)$(id).close();}
document.querySelectorAll('[data-close-dialog]').forEach(button=>button.onclick=()=>closeDialog(button.dataset.closeDialog));

async function loadWorkspace(){
 try{
  const allowed=await request('/rest/v1/admin_users?select=user_id',{},true);
  if(!allowed?.some(row=>row.user_id===session.user.id)){saveSession(null);throw Error('Este usuário não foi autorizado para administrar a C CAR.');}
  const [vehicleRows,privateRows]=await Promise.all([request('/rest/v1/vehicles?select=*&order=created_at.desc',{},true),request('/rest/v1/vehicle_private?select=vehicle_id,plate,chassis,renavam',{},true)]);
  vehicles=vehicleRows||[];privateIndex=new Map((privateRows||[]).map(row=>[row.vehicle_id,row]));await loadMetrics();
  $('adminLogin').hidden=true;$('adminWorkspace').hidden=false;$('adminIdentity').textContent=session.user.email||'Usuário autorizado';renderAll();
 }catch(error){showLogin(error.message);}
}
async function loadMetrics(){const days=Number($('dashboardPeriod').value);try{const [vehicleMetrics,series]=await Promise.all([request('/rest/v1/rpc/get_dashboard_vehicle_insights',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({p_days:days})},true),request('/rest/v1/rpc/get_dashboard_timeseries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({p_days:days})},true)]);insights=new Map((vehicleMetrics||[]).map(row=>[row.vehicle_id,row]));dailySeries=series||[];}catch(_){insights=new Map();dailySeries=[];}}
function metricFor(id){return insights.get(id)||{views:0,contacts:0};}
function renderStats(){
 const published=vehicles.filter(v=>v.status==='published'),drafts=vehicles.filter(v=>v.status==='draft').length,views=[...insights.values()].reduce((sum,row)=>sum+Number(row.views||0),0),contacts=[...insights.values()].reduce((sum,row)=>sum+Number(row.contacts||0),0),days=Number($('dashboardPeriod').value);
 $('statPublished').textContent=published.length;$('statDraft').textContent=drafts+' rascunho'+(drafts===1?'':'s');$('statInventoryValue').textContent=money(published.reduce((sum,v)=>sum+Number(v.price||0),0));$('statViews').textContent=views.toLocaleString('pt-BR');$('statContacts').textContent=contacts.toLocaleString('pt-BR');$('statContactRate').textContent=(views?contacts/views*100:0).toLocaleString('pt-BR',{maximumFractionDigits:1})+'%';$('statViewsPeriod').textContent=$('statContactsPeriod').textContent='últimos '+days+' dias';$('inventoryTabCount').textContent=vehicles.length;
}
function renderTrendChart(){const svg=$('trendChart'),rows=dailySeries.length?dailySeries:Array.from({length:Number($('dashboardPeriod').value)},(_,i)=>({event_day:new Date(Date.now()-(Number($('dashboardPeriod').value)-1-i)*86400000).toISOString().slice(0,10),views:0,contacts:0})),width=760,height=270,left=42,right=15,top=18,bottom=36,plotW=width-left-right,plotH=height-top-bottom,max=Math.max(1,...rows.flatMap(row=>[Number(row.views),Number(row.contacts)]));const point=(row,index,key)=>[left+(rows.length===1?0:index/(rows.length-1))*plotW,top+(1-Number(row[key])/max)*plotH];const path=key=>rows.map((row,index)=>{const[x,y]=point(row,index,key);return(index?'L':'M')+x.toFixed(1)+' '+y.toFixed(1);}).join(' '),area=path('views')+` L ${left+plotW} ${top+plotH} L ${left} ${top+plotH} Z`,ticks=[0,.5,1];svg.innerHTML=`<defs><linearGradient id="viewsArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#c9aa70" stop-opacity=".25"/><stop offset="1" stop-color="#c9aa70" stop-opacity="0"/></linearGradient></defs>${ticks.map(ratio=>{const y=top+(1-ratio)*plotH;return `<line class="chart-grid-line" x1="${left}" y1="${y}" x2="${left+plotW}" y2="${y}"/><text class="chart-axis-label" x="${left-8}" y="${y+3}" text-anchor="end">${Math.round(max*ratio)}</text>`;}).join('')}<path class="chart-area" d="${area}"/><path class="chart-line-views" d="${path('views')}"/><path class="chart-line-contacts" d="${path('contacts')}"/>${[0,Math.floor((rows.length-1)/2),rows.length-1].filter((v,i,a)=>a.indexOf(v)===i).map(index=>{const[x]=point(rows[index],index,'views'),date=new Date(rows[index].event_day+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});return `<text class="chart-axis-label" x="${x}" y="${height-9}" text-anchor="middle">${date}</text>`;}).join('')}`;}
function renderStatusBreakdown(){const counts={published:vehicles.filter(v=>v.status==='published').length,draft:vehicles.filter(v=>v.status==='draft').length,sold:vehicles.filter(v=>v.status==='sold').length},total=Math.max(1,vehicles.length);$('statusBreakdown').innerHTML=['published','draft','sold'].map(status=>`<div class="status-row ${status}"><div class="status-row-head"><span>${statusLabel[status]}</span><strong>${counts[status]}</strong></div><div class="status-track"><span style="width:${counts[status]/total*100}%"></span></div></div>`).join('')+`<div class="status-total"><span>Total cadastrado</span><strong>${vehicles.length} veículo${vehicles.length===1?'':'s'}</strong></div>`;}
function renderTopVehicles(){const ranked=vehicles.filter(v=>v.status==='published').map(v=>({vehicle:v,metric:metricFor(v.id)})).sort((a,b)=>Number(b.metric.views)-Number(a.metric.views)||Number(b.metric.contacts)-Number(a.metric.contacts)).slice(0,5);$('topVehicles').innerHTML=ranked.length?ranked.map(({vehicle,metric},index)=>`<div class="top-vehicle-row"><span class="top-vehicle-rank">${String(index+1).padStart(2,'0')}</span><div class="top-vehicle-name"><strong>${safe(vehicle.make+' '+vehicle.model)}</strong><span>${safe(vehicle.version||vehicle.year)}</span></div><div class="top-vehicle-number"><strong>${Number(metric.views||0)}</strong><span>VISUALIZAÇÕES</span></div><div class="top-vehicle-number contacts-column"><strong>${Number(metric.contacts||0)}</strong><span>CONTATOS</span></div></div>`).join(''):'<div class="dashboard-empty">Publique um veículo para iniciar o acompanhamento.</div>';}
function renderAttention(){const drafts=vehicles.filter(v=>v.status==='draft').length,noPhotos=vehicles.filter(v=>v.status==='published'&&!v.photos?.length).length,incomplete=vehicles.filter(v=>{const data=privateIndex.get(v.id);return !data?.plate||!data.chassis||!data.renavam;}).length,items=[];if(drafts)items.push({label:drafts+' rascunho'+(drafts===1?'':'s')+' aguardando publicação',detail:'Revise os anúncios antes de publicar',filter:'draft'});if(noPhotos)items.push({label:noPhotos+' anúncio'+(noPhotos===1?'':'s')+' sem foto',detail:'Fotos aumentam a qualidade do catálogo',filter:'published'});if(incomplete)items.push({label:incomplete+' ficha'+(incomplete===1?'':'s')+' documental incompleta'+(incomplete===1?'':'s'),detail:'Confira placa, chassi e Renavam',filter:''});if(!items.length)items.push({label:'Cadastro em dia',detail:'Nenhuma pendência identificada',ok:true});$('attentionList').innerHTML=items.map(item=>`<div class="attention-item${item.ok?' ok':''}"><span class="attention-dot"></span><div><strong>${item.label}</strong><span>${item.detail}</span></div>${item.ok?'':'<button data-attention-filter="'+item.filter+'">Revisar</button>'}</div>`).join('');}
function renderVehicles(){
 const term=$('adminSearch').value.trim().toLocaleLowerCase('pt-BR'),filter=$('adminFilter').value;
 const list=vehicles.filter(v=>(!filter||v.status===filter)&&[v.make,v.model,v.version].join(' ').toLocaleLowerCase('pt-BR').includes(term));
 $('adminVehicleGrid').innerHTML=list.length?list.map(v=>{const m=metricFor(v.id),days=v.published_at?Math.max(0,Math.floor((Date.now()-new Date(v.published_at).getTime())/86400000)):null,period=$('dashboardPeriod').value;return `<article class="admin-vehicle-card"><img class="admin-vehicle-image${v.photos?.length?'':' placeholder'}" src="${v.photos?.length?safe(photoURL(v.photos[0])):'assets/logo.png'}" alt="${safe(v.make+' '+v.model)}"><div class="admin-vehicle-content"><div class="admin-vehicle-top"><div><span class="eyebrow">${safe(v.category)} · ${safe(v.year)}</span><h3>${safe(v.make)} ${safe(v.model)}</h3></div><span class="admin-status-badge ${safe(v.status)}">${statusLabel[v.status]}</span></div><p class="admin-vehicle-meta">${safe(v.version)} · ${money(v.price)}${days!==null?' · '+days+' dia'+(days===1?'':'s')+' publicado':''}</p><div class="admin-insights"><div><strong>${Number(m.views||0)}</strong><span>VISUALIZAÇÕES · ${period}D</span></div><div><strong>${Number(m.contacts||0)}</strong><span>CONTATOS · ${period}D</span></div><div><strong>${Number(m.views)?(Number(m.contacts||0)/Number(m.views)*100).toLocaleString('pt-BR',{maximumFractionDigits:1})+'%':'0%'}</strong><span>TAXA DE INTERESSE</span></div></div><div class="admin-card-actions"><button class="primary" data-action="edit" data-id="${safe(v.id)}">Editar</button><button data-action="private" data-id="${safe(v.id)}">Dados privados / Word</button><button data-action="duplicate" data-id="${safe(v.id)}">Duplicar</button><select data-action="status" data-id="${safe(v.id)}" aria-label="Alterar status"><option value="draft"${v.status==='draft'?' selected':''}>Rascunho</option><option value="published"${v.status==='published'?' selected':''}>Disponível</option><option value="sold"${v.status==='sold'?' selected':''}>Vendido</option></select><button class="danger" data-action="delete" data-id="${safe(v.id)}">Excluir</button></div></div></article>`;}).join(''):'<div class="admin-empty"><h3>Nenhum veículo encontrado.</h3><p>Adicione o primeiro veículo ou altere os filtros.</p></div>';
}
function renderAll(){renderStats();renderTrendChart();renderStatusBreakdown();renderTopVehicles();renderAttention();renderVehicles();}
function activateTab(name){document.querySelectorAll('[data-admin-tab]').forEach(button=>{const active=button.dataset.adminTab===name;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));});$('overviewPanel').hidden=name!=='overview';$('inventoryPanel').hidden=name!=='inventory';}
document.querySelectorAll('[data-admin-tab]').forEach(button=>button.onclick=()=>activateTab(button.dataset.adminTab));
document.querySelectorAll('[data-go-inventory]').forEach(button=>button.onclick=()=>activateTab('inventory'));
$('attentionList').addEventListener('click',event=>{const button=event.target.closest('[data-attention-filter]');if(!button)return;$('adminFilter').value=button.dataset.attentionFilter;activateTab('inventory');renderVehicles();});
$('dashboardPeriod').addEventListener('change',async()=>{$('dashboardPeriod').disabled=true;try{await loadMetrics();renderAll();}finally{$('dashboardPeriod').disabled=false;}});
$('adminSearch').addEventListener('input',renderVehicles);$('adminFilter').addEventListener('change',renderVehicles);
$('adminVehicleGrid').addEventListener('click',event=>{const button=event.target.closest('button[data-action]');if(!button)return;const vehicle=vehicles.find(v=>v.id===button.dataset.id);if(!vehicle)return;({edit:openVehicle,private:openPrivate,duplicate:duplicateVehicle,delete:deleteVehicle}[button.dataset.action])?.(vehicle);});
$('adminVehicleGrid').addEventListener('change',event=>{const select=event.target.closest('select[data-action="status"]');if(select)changeStatus(select.dataset.id,select.value,select);});

$('adminLoginForm').onsubmit=async event=>{event.preventDefault();$('adminLoginButton').disabled=true;$('adminSetupNotice').hidden=true;try{const result=await request('/auth/v1/token?grant_type=password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('adminEmail').value.trim(),password:$('adminPassword').value})});saveSession({...result,expires_at:Date.now()/1000+result.expires_in});$('adminPassword').value='';await loadWorkspace();}catch(_){showLogin('Não foi possível entrar. Confira e-mail, senha e autorização da equipe.');}finally{$('adminLoginButton').disabled=!connected;}};
$('adminLogout').onclick=async()=>{await request('/auth/v1/logout',{method:'POST'},true).catch(()=>{});saveSession(null);showLogin();};

function openVehicle(vehicle=null){clearPreviews();$('adminVehicleForm').reset();$('adminVehicleId').value=vehicle?.id||'';$('vehicleDialogTitle').textContent=vehicle?'Editar veículo':'Novo veículo';photoItems=(vehicle?.photos||[]).map(path=>({kind:'existing',path}));if(vehicle){const values={adminMake:'make',adminModel:'model',adminVersion:'version',adminYear:'year',adminPrice:'price',adminKm:'km',adminTransmission:'transmission',adminCategory:'category',adminFuel:'fuel',adminVehicleStatus:'status',adminDescription:'description'};for(const[id,key]of Object.entries(values))$(id).value=vehicle[key]??'';$('adminFeatured').checked=vehicle.featured;}renderPhotos();$('vehicleDialog').showModal();}
$('addVehicle').onclick=()=>openVehicle();
function movePhoto(from,to){if(to<0||to>=photoItems.length||from===to)return;const[item]=photoItems.splice(from,1);photoItems.splice(to,0,item);renderPhotos();}
function removePhoto(index){const[item]=photoItems.splice(index,1);if(item?.kind==='new')URL.revokeObjectURL(item.url);renderPhotos();}
function renderPhotos(){const gallery=$('adminPhotoPreview');gallery.innerHTML=photoItems.map((item,index)=>`<figure draggable="true" data-photo-index="${index}" class="${item.kind==='new'?'new-photo':''}"><img src="${safe(item.kind==='existing'?photoURL(item.path):item.url)}" alt="Foto ${index+1}">${index===0?'<span class="cover-label">Capa</span>':''}<span class="photo-position">${index+1}</span><div class="photo-controls"><button type="button" data-photo-move="left" data-photo-index="${index}" aria-label="Mover foto para a esquerda"${index===0?' disabled':''}>←</button><button type="button" data-photo-move="right" data-photo-index="${index}" aria-label="Mover foto para a direita"${index===photoItems.length-1?' disabled':''}>→</button><button type="button" data-photo-remove data-photo-index="${index}" aria-label="Remover foto">Remover</button></div></figure>`).join('');gallery.querySelectorAll('[data-photo-move]').forEach(button=>button.onclick=()=>movePhoto(+button.dataset.photoIndex,+button.dataset.photoIndex+(button.dataset.photoMove==='left'?-1:1)));gallery.querySelectorAll('[data-photo-remove]').forEach(button=>button.onclick=()=>removePhoto(+button.dataset.photoIndex));gallery.querySelectorAll('[draggable]').forEach(figure=>{figure.ondragstart=()=>{draggedPhotoIndex=+figure.dataset.photoIndex;figure.classList.add('dragging');};figure.ondragend=()=>{draggedPhotoIndex=null;figure.classList.remove('dragging');};figure.ondragover=event=>{event.preventDefault();figure.classList.add('drag-over');};figure.ondragleave=()=>figure.classList.remove('drag-over');figure.ondrop=event=>{event.preventDefault();figure.classList.remove('drag-over');if(draggedPhotoIndex!==null)movePhoto(draggedPhotoIndex,+figure.dataset.photoIndex);};});}
$('adminPhotos').onchange=()=>{for(const file of $('adminPhotos').files)photoItems.push({kind:'new',file,url:URL.createObjectURL(file)});$('adminPhotos').value='';renderPhotos();};
$('adminVehicleForm').onsubmit=async event=>{event.preventDefault();const newItems=photoItems.filter(item=>item.kind==='new'),files=newItems.map(item=>item.file);if(photoItems.length>30){message('Use no máximo 30 fotos por veículo.',true);return;}if(files.some(file=>!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15*1024*1024)){message('Use fotos JPEG, PNG ou WebP de até 15 MB.',true);return;}$('saveAdminVehicle').disabled=true;const id=$('adminVehicleId').value||crypto.randomUUID(),uploads=[];let saved=false;try{const photos=[];let uploadNumber=0;for(const item of photoItems){if(item.kind==='existing'){photos.push(item.path);continue;}uploadNumber++;message(`Enviando foto ${uploadNumber} de ${newItems.length}…`);const file=item.file,extension={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type],path=id+'/'+crypto.randomUUID()+'.'+extension;await request('/storage/v1/object/vehicle-photos/'+path,{method:'POST',headers:{'Content-Type':file.type,'Cache-Control':'max-age=31536000'},body:file},true);uploads.push(path);photos.push(path);}const record={id,make:$('adminMake').value.trim(),model:$('adminModel').value.trim(),version:$('adminVersion').value.trim(),year:+$('adminYear').value,price:+$('adminPrice').value,km:+$('adminKm').value,transmission:$('adminTransmission').value,category:$('adminCategory').value,fuel:$('adminFuel').value,status:$('adminVehicleStatus').value,description:$('adminDescription').value.trim(),featured:$('adminFeatured').checked,photos};const old=vehicles.find(v=>v.id===id);await request('/rest/v1/vehicles'+(old?'?id=eq.'+encodeURIComponent(id):''),{method:old?'PATCH':'POST',headers:{'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify(record)},true);saved=true;const removed=old?.photos?.filter(path=>!photos.includes(path))||[];if(removed.length)await request('/storage/v1/object/vehicle-photos',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({prefixes:removed})},true);closeDialog('vehicleDialog');clearPreviews();await loadWorkspace();message('Veículo salvo com sucesso.');}catch(error){if(!saved&&uploads.length)await request('/storage/v1/object/vehicle-photos',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({prefixes:uploads})},true).catch(()=>{});message(error.message,true);}finally{$('saveAdminVehicle').disabled=false;}};
async function changeStatus(id,status,select){select.disabled=true;try{await request('/rest/v1/vehicles?id=eq.'+encodeURIComponent(id),{method:'PATCH',headers:{'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify({status})},true);await loadWorkspace();message('Status atualizado.');}catch(error){message(error.message,true);await loadWorkspace();}finally{select.disabled=false;}}
async function duplicateVehicle(vehicle){if(!confirm(`Criar uma cópia em rascunho de ${vehicle.make} ${vehicle.model}? As fotos não serão copiadas.`))return;const copy={id:crypto.randomUUID(),make:vehicle.make,model:vehicle.model,version:vehicle.version,year:vehicle.year,price:vehicle.price,km:vehicle.km,transmission:vehicle.transmission,category:vehicle.category,fuel:vehicle.fuel,status:'draft',description:vehicle.description,featured:false,photos:[]};try{await request('/rest/v1/vehicles',{method:'POST',headers:{'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify(copy)},true);await loadWorkspace();message('Cópia criada como rascunho.');}catch(error){message(error.message,true);}}
async function deleteVehicle(vehicle){if(!confirm(`Excluir ${vehicle.make} ${vehicle.model} e suas fotos? Esta ação não pode ser desfeita.`))return;try{await request('/rest/v1/vehicles?id=eq.'+encodeURIComponent(vehicle.id),{method:'DELETE'},true);if(vehicle.photos?.length)await request('/storage/v1/object/vehicle-photos',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({prefixes:vehicle.photos})},true);await loadWorkspace();message('Veículo excluído.');}catch(error){message(error.message,true);}}

const privateFields={adminPrivatePlate:'plate',adminPrivateChassis:'chassis',adminPrivateRenavam:'renavam',adminPrivateColor:'color',adminPrivateOwner:'owner_name',adminPrivateOwnerDocument:'owner_document',adminPrivateNotes:'internal_notes',adminPrivateEngine:'engine_number',adminPrivateRegistrationCategory:'registration_category',adminPrivatePower:'power_displacement'};
async function openPrivate(vehicle){message('Carregando dados privados…');try{const rows=await request('/rest/v1/vehicle_private?vehicle_id=eq.'+encodeURIComponent(vehicle.id)+'&select=*',{},true),record=rows?.[0]||{};currentPrivateVehicle=vehicle;$('adminPrivateForm').reset();for(const[field,key]of Object.entries(privateFields))$(field).value=record[key]||'';$('adminPrivateCost').value=record.acquisition_cost??'';$('adminPrivateFabricationYear').value=record.fabrication_year??'';$('privateDialogTitle').textContent=vehicle.make+' '+vehicle.model+' · Dados privados';$('privateDialog').showModal();message('');}catch(_){message('Não foi possível carregar os dados privados.',true);}}
async function savePrivate(){if(!currentPrivateVehicle)throw Error('Selecione um veículo.');const record={vehicle_id:currentPrivateVehicle.id,fabrication_year:$('adminPrivateFabricationYear').value===''?null:Number($('adminPrivateFabricationYear').value),acquisition_cost:$('adminPrivateCost').value===''?null:Number($('adminPrivateCost').value)};for(const[field,key]of Object.entries(privateFields))record[key]=$(field).value.trim();await request('/rest/v1/vehicle_private?on_conflict=vehicle_id',{method:'POST',headers:{'Content-Type':'application/json',Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(record)},true);return record;}
$('adminPrivateForm').onsubmit=async event=>{event.preventDefault();$('saveAdminPrivate').disabled=true;try{await savePrivate();message('Dados privados salvos.');closeDialog('privateDialog');}catch(error){message(error.message,true);}finally{$('saveAdminPrivate').disabled=false;}};
async function getCompany(){const rows=await request('/rest/v1/company_settings?id=eq.1&select=*',{},true);return rows?.[0]||null;}
$('openCompany').onclick=async()=>{try{const company=await getCompany();const values={adminLegalName:'legal_name',adminCompanyCnpj:'cnpj',adminCompanyAddress:'address',adminRepresentative:'representative',adminRepresentativeRole:'representative_role'};for(const[field,key]of Object.entries(values))$(field).value=company?.[key]||'';$('companyDialog').showModal();}catch(_){message('Não foi possível carregar o cadastro da loja.',true);}};
$('generateAdminWord').onclick=async()=>{$('generateAdminWord').disabled=true;try{const company=await getCompany();if(!company?.legal_name||!company.cnpj||!company.address)throw Error('O cadastro fixo da loja está incompleto.');const record=await savePrivate(),blob=await window.CCAR_DOCUMENTS.build(currentPrivateVehicle,record,company,$('adminDocumentType').value),name=('C-CAR-'+currentPrivateVehicle.make+'-'+currentPrivateVehicle.model+'-'+(record.plate||currentPrivateVehicle.id)).replace(/[^a-zA-Z0-9-]/g,'-')+'.docx';window.CCAR_DOCUMENTS.download(blob,name);message('Documento gerado. Confira os dados antes de usar.');}catch(error){message(error.message,true);}finally{$('generateAdminWord').disabled=false;}};

